enum UserRole { guest, buyer, seller, admin, superAdmin }
enum AuthStatus { loggedOut, otpRequested, otpVerified, profileIncomplete, loggedIn, suspended, sessionExpired }
class AuthUser { const AuthUser({required this.id, required this.role, this.displayName, this.profileComplete = true}); final String id; final UserRole role; final String? displayName; final bool profileComplete; Map<String,Object?> toJson()=>{'id':id,'role':role.name,'displayName':displayName,'profileComplete':profileComplete}; factory AuthUser.fromJson(Map<String,Object?> j)=>AuthUser(id:j['id']! as String,role:UserRole.values.byName(j['role']! as String),displayName:j['displayName'] as String?,profileComplete:j['profileComplete'] as bool? ?? true); }
class AuthSession { const AuthSession({this.user, required this.status, this.tokenPlaceholder, this.expiresAt}); final AuthUser? user; final AuthStatus status; final String? tokenPlaceholder; final DateTime? expiresAt; UserRole get role=>user?.role??UserRole.guest; bool get isExpired=>expiresAt?.isBefore(DateTime.now())??false; AuthSession copyWith({AuthUser? user,AuthStatus? status,String? tokenPlaceholder,DateTime? expiresAt,bool clearUser=false})=>AuthSession(user:clearUser?null:user??this.user,status:status??this.status,tokenPlaceholder:tokenPlaceholder??this.tokenPlaceholder,expiresAt:expiresAt??this.expiresAt); Map<String,Object?> toJson()=>{'user':user?.toJson(),'status':status.name,'expiresAt':expiresAt?.toIso8601String()}; factory AuthSession.fromJson(Map<String,Object?> j)=>AuthSession(user:j['user']==null?null:AuthUser.fromJson(Map<String,Object?>.from(j['user']! as Map)),status:AuthStatus.values.byName(j['status']! as String),expiresAt:j['expiresAt']==null?null:DateTime.parse(j['expiresAt']! as String)); static const loggedOut=AuthSession(status:AuthStatus.loggedOut); }
